// ===== 哔咔漫画 自包含库 (v84) =====
// 作用域铁律：jsLib 在独立 ScriptBindings 求值，只有函数定义被 chainTo 共享；
// source/java/baseUrl/result 在此不存在 => 一律参数注入 (SRC, JV)，禁止裸引用。
// 本次全部改名（picab_ -> picac_ / PICAB_ -> PICAC_），规避 Rhino SharedJsScope 编译缓存。
var PICA = {
  API_KEY: "C69BAF41DA5ABD1FFEDC6D2FEA56B",
  SECRET: "~d}$Q7$eIni=V)9" + String.fromCharCode(92) + "RK/P.RM4;9[7|@/CA}b~OW!3?EV" + String.fromCharCode(96, 58, 60, 62) + "M7pddUBL5n|0/*Cn",
  BASE: "https://picaapi.picacomic.com/",
  DNS_POOL: ["172.67.194.19", "172.67.80.1", "104.21.235.3",
             "104.21.235.4", "104.21.91.145", "104.19.53.76",
             "104.21.80.1", "104.21.81.1", "104.16.0.1", "104.17.0.1"],
  INIT_URL: "http://68.183.234.72/init",
  MIRROR: "https://s3.go2778.com"
};

function picac_hash(s) {
  var h = 0;
  s = String(s || "");
  for (var i = 0; i < s.length; i++) {
    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

function picac_bytes(str) {
  return new Packages.java.lang.String(str).getBytes("UTF-8");
}

function picac_hmac(raw, key) {
  var m = Packages.javax.crypto.Mac.getInstance("HmacSHA256");
  m.init(new Packages.javax.crypto.spec.SecretKeySpec(picac_bytes(key), "HmacSHA256"));
  var b = m.doFinal(picac_bytes(raw));
  var s = "";
  for (var i = 0; i < b.length; i++) {
    var x = b[i] & 0xff;
    s += (x < 16 ? "0" : "") + x.toString(16);
  }
  return s;
}

function picac_nonce() {
  var s = "";
  for (var i = 0; i < 32; i++) {
    s += "0123456789abcdef".charAt(Math.floor(Math.random() * 16));
  }
  return s;
}

function picac_token(SRC) {
  try {
    var h = String(SRC.getLoginHeader() || "");
    if (h && h !== "null") {
      var m = h.match(new RegExp('"authorization"\\s*:\\s*"([^"]+)"'));
      if (m) { return m[1]; }
      return h;
    }
  } catch (e0) {}
  try { return String(SRC.get("picab_token") || ""); } catch (e1) { return ""; }
}

function picac_official(SRC) {
  try { return String(SRC.get("picab_official_ips") || ""); } catch (e0) { return ""; }
}

function picac_pool(SRC) {
  var p = "";
  try { p = String(SRC.get("picab_pool") || ""); } catch (e0) {}
  if (p === "none") { return ""; }
  if (p) { return p; }
  return PICA.DNS_POOL.join(",");
}

function picac_stationName(idx) {
  return ({ "0": "官方init", "1": "Cloudflare", "2": "系统DNS直连" })[String(idx)] || "未知";
}

function picac_currentStation(SRC) {
  try { return String(SRC.get("picab_station") || "1"); } catch (e0) { return "1"; }
}

function picac_coverMode(SRC) {
  try {
    var m = String(SRC.get("picab_cover_mode") || "ip");
    return (m === "dns" || m === "mirror") ? m : "ip";
  } catch (e0) { return "ip"; }
}

function picac_buildPool(station, official) {
  var out = [];
  function add(ip) {
    ip = String(ip || "").trim();
    if (ip && ip.indexOf(".") > 0 && out.indexOf(ip) < 0) { out.push(ip); }
  }
  if (station === "0") {
    String(official || "").split(",").forEach(add);
    PICA.DNS_POOL.forEach(add);
  } else if (station === "1") {
    PICA.DNS_POOL.forEach(add);
  } else {
    return "none";
  }
  return out.join(",");
}

function picac_headers(path, method, SRC, JV) {
  var ts = String(Math.floor(Date.now() / 1000));
  var nonce = picac_nonce();
  var raw = (path + ts + nonce + method + PICA.API_KEY).toLowerCase();
  var sig = picac_hmac(raw, PICA.SECRET);
  var h = {
    "User-Agent": "okhttp/3.8.1",
    "accept": "application/vnd.picacomic.com.v1+json",
    "api-key": PICA.API_KEY,
    "app-channel": "2",
    "app-version": "2.2.1.2.3.3",
    "app-uuid": "defaultUuid",
    "app-platform": "android",
    "app-build-version": "44",
    "image-quality": "original",
    "time": ts,
    "nonce": nonce,
    "signature": sig
  };
  var tk = picac_token(SRC);
  if (tk && tk !== "null" && tk !== "") { h["authorization"] = tk; }
  return h;
}

function picac_opt(path, opt, SRC, JV) {
  opt = opt || {};
  opt.headers = picac_headers(path, opt.method || "GET", SRC, JV);
  if ((opt.method || "GET") === "POST") {
    opt.headers["Content-Type"] = "application/json; charset=UTF-8";
  }
  var dp = picac_pool(SRC);
  if (dp && !opt.dnsIp) { opt.dnsIp = dp; }
  if (!opt.retry) { opt.retry = 4; }
  if (!opt.timeout) { opt.timeout = 25000; }
  return PICA.BASE + path + "," + JSON.stringify(opt);
}

function picac_get(path, SRC, JV) {
  var last = "";
  for (var i = 0; i < 3; i++) {
    last = String(JV.ajax(picac_opt(path, { method: "GET" }, SRC, JV)) || "");
    if (last.charAt(0) === "{") { return last; }
    if (i < 2) {
      try { Packages.java.lang.Thread.sleep(1500); } catch (e0) {}
    }
  }
  return last;
}

function picac_post(path, bodyObj, SRC, JV) {
  var last = "";
  for (var i = 0; i < 3; i++) {
    last = String(JV.ajax(picac_opt(path, { method: "POST", body: JSON.stringify(bodyObj) }, SRC, JV)) || "");
    if (last.charAt(0) === "{") { return last; }
    if (i < 2) {
      try { Packages.java.lang.Thread.sleep(1500); } catch (e0) {}
    }
  }
  return last;
}
// ---------- 封面 ----------
/* 解析 thumb：
   tobeimg/<hash>/rs:fill:W:H:0/g:sm/<base64>[.jpg]  → base64 解出真实图片 URL
   tobs/<file>                                          → /static/<file>（去掉 tobs/ 前缀）
   <file>                                               → /static/<file>
   返回 {host, path, raw, real, isSB} */
function picac_parseThumb(media) {
  var out = { host: "", path: "", raw: "", real: "", isSB: false };
  if (!media) { return out; }
  var fs = String(media.fileServer || "").replace(new RegExp("/$"), "");
  var path = String(media.path || "").replace(new RegExp("^/?"), "");
  out.raw = path;
  if (!path) { return out; }
  if (path.indexOf("tobeimg/") === 0) {
    var idx = path.indexOf("/g:sm/");
    if (idx >= 0) {
      var b64 = path.substring(idx + 6);
      var m = b64.match(new RegExp("^([A-Za-z0-9+/=]+)(\\.[A-Za-z0-9]+)?$"));
      if (m) {
        try {
          var pay = m[1];
          while (pay.length % 4 !== 0) { pay += "="; }
          var real = String(new Packages.java.lang.String(
              Packages.android.util.Base64.decode(pay, 0), "UTF-8"));
          var i2 = real.indexOf("/static/");
          if (i2 >= 0) {
            out.real = real;
            out.host = real.substring(0, i2).replace(new RegExp("^https?://"), "");
            out.path = real.substring(i2);
            out.isSB = out.host.indexOf("storage-b") >= 0;
            return out;
          }
        } catch (e0) {}
      }
    }
  }
  out.host = fs.replace(new RegExp("^https?://"), "");
  if (path.indexOf("tobs/") === 0) { path = path.substring(5); }
  out.path = "/static/" + path;
  out.isSB = out.host.indexOf("storage-b") >= 0;
  return out;
}

/* 图片 URL（封面与正文共用一套规则）
   关键：漫画浏览模式走 Glide → AnalyzeUrl.getGlideUrl()，
        该方法【只保留 url + headerMap，丢弃 dnsIp】⇒
        域名直连在 IPv6 优先的网络里必然超时。
        所以图片 URL 必须自带 IP 直连能力：
        storage-b → http://<CF-IP><path> + {"headers":{"Host":"storage-b.picacomic.com"}}
        Host 头在 OkHttp BridgeInterceptor 只在缺失时补 ⇒ 保留；
        同时对普通浏览模式（getByteArrayAwait，dnsIp 生效）也完全兼容。
   其它域（storage1 等）真机不可达 ⇒ 回退域名直连。 */
function picac_imgUrl(media, SRC) {
  var t = picac_parseThumb(media);
  if (!t.path) { return ""; }
  var mode = "ip";
  try { mode = picac_coverMode(SRC); } catch (e0) {}
  if (mode === "dns") {
    return "https://" + t.host + t.path;
  }
  if (t.isSB) {
    var ips = PICA.DNS_POOL;
    var ip = ips[picac_hash(t.path) % ips.length];
    return "http://" + ip + t.path
         + ',{"method":"GET","timeout":30000,"headers":{"Host":"' + t.host + '"}}';
  }
  return "https://" + t.host + t.path;
}

/* 封面 URL（三种模式，由 picab_cover_mode 控制）：
   ip     → storage-b 用 IP+Host 头；其它域域名直连
   dns    → 全部域名直连
   mirror → 参考源同款镜像 s3.go2778.com（保留原始 tobeimg 路径） */
function picac_cover(media, SRC) {
  var t = picac_parseThumb(media);
  if (!t.raw) { return ""; }
  var mode = picac_coverMode(SRC);
  if (mode === "mirror") {
    return PICA.MIRROR + "/static/" + t.raw;
  }
  if (!t.host) { return ""; }
  if (mode === "dns") {
    return "https://" + t.host + t.path;
  }
  if (t.isSB) {
    var ips = PICA.DNS_POOL;
    var ip = ips[picac_hash(t.path) % ips.length];
    return "http://" + ip + t.path
         + ',{"method":"GET","timeout":20000,"headers":{"Host":"' + t.host + '"}}';
  }
  return "https://" + t.host + t.path;
}

/* 正文图片 URL：与封面同规则（IP+Host 头），保证漫画浏览模式也能加载 */
function picac_img(media, SRC) {
  return picac_imgUrl(media, SRC);
}

function picac_bookid(u) {
  var s = String(u || "");
  var c = s.indexOf(",{");
  if (c >= 0) { s = s.substring(0, c); }
  var m = s.match(new RegExp("comics/([0-9a-fA-F]{24})"));
  if (m) { return m[1]; }
  m = s.match(new RegExp("^([0-9a-fA-F]{24})$"));
  return m ? m[1] : "";
}

function picac_item(c, SRC, JV) {
  if (!c) { return null; }
  return {
    name: c.title || "",
    author: c.author || "",
    cover: picac_cover(c.thumb, SRC),
    intro: "",
    kind: [(c.__group || ""),
           String(c.categories || []).replace(/,/g, " "),
           c.finished ? "完结" : "连载",
           c.likesCount ? c.likesCount + "♥" : ""].filter(Boolean).join(" · "),
    latest: "",
    word: "",
    url: PICA.BASE + "comics/" + (c._id || "")
        + ',{"method":"GET","retry":3,"timeout":20000,'
        + '"headers":' + JSON.stringify(picac_headers("comics/" + (c._id || ""), "GET", SRC))
        + ',"dnsIp":"' + picac_pool(SRC) + '"}'
  };
}

function picac_list(data) {
  var d = data || {};
  if (d.collections) {
    var flat = [];
    (d.collections || []).forEach(function (g) {
      (g.comics || []).forEach(function (c) {
        c.__group = g.title;
        flat.push(c);
      });
    });
    return flat;
  }
  var list = d.comics ? (d.comics.docs || d.comics) : (d.docs || d);
  if (!Array.isArray(list)) { list = []; }
  return list;
}

function picac_say(jv, msg) {
  var stamped = "[" + new Date().toTimeString().substring(0, 8) + "] " + msg;
  try { jv.upLoginData({ "登录状态": stamped }); } catch (e1) {}
  try { jv.toast(stamped); } catch (e2) {}
  try { jv.longToast(stamped); } catch (e3) {}
  try { jv.reLoginView(false); } catch (e4) {}
}
function PICAC_checkLogin(jv, SRC) {
  var msg = "";
  try {
    var txt = String(jv.ajax(picac_opt("users/profile", { method: "GET" }, SRC, jv)) || "");
    if (!txt) { msg = "检查失败: 无响应"; }
    else if (txt.charAt(0) !== "{") {
      msg = "❌ 检查失败: 网络超时（试试切换源站）";
      picac_say(jv, msg); return;
    } else {
      var jo = null;
      try { jo = JSON.parse(txt); } catch (e3) {}
      if (jo && jo.code === 200 && jo.data && jo.data.user) {
        var u = jo.data.user;
        msg = "✅ 已登录: " + (u.name || u.email || "未知")
              + " (Lv." + (u.level || "?") + ")"
              + (u.isPunched ? " [今日已签到]" : " [今日未签到]");
      } else if (jo && (jo.code === 401 || jo.code === 403)) {
        msg = "❌ 未登录，请填账号密码后点右上角✓登录";
      } else {
        msg = "⚠️ 状态未知: " + txt.substring(0, 60);
      }
    }
  } catch (e) { msg = "检查失败: " + e; }
  picac_say(jv, msg);
}

function PICAC_punch(jv, SRC) {
  var msg = "";
  try {
    var txt = String(jv.ajax(picac_opt("users/punch-in",
        { method: "POST", body: "{}" }, SRC, jv)) || "");
    if (!txt) { msg = "签到失败: 无响应"; }
    else if (txt.charAt(0) !== "{") {
      var why = txt.indexOf("SocketTimeout") >= 0 ? "网络超时" : "网络错误";
      msg = "❌ 签到失败: " + why + "（可试「🔄源站更新」或切换源站）";
      picac_say(jv, msg); return;
    }
    var jo = null;
    try { jo = JSON.parse(txt); } catch (e0) {}
    if (jo && jo.code === 200 && jo.data && jo.data.res) {
      var st = String(jo.data.res.status || "");
      if (st === "ok") { msg = "✅ 签到成功 (最近签到日 " + (jo.data.res.punchInLastDay || "?") + ")"; }
      else if (st === "fail") { msg = "📌 今日已签到，无需重复"; }
      else { msg = "签到状态: " + st; }
    } else if (jo && (jo.code === 401 || jo.code === 403)) {
      msg = "❌ 未登录，请先登录再签到";
    } else {
      msg = "❌ 签到失败: " + (jo && jo.message ? jo.message : txt.substring(0, 80));
    }
  } catch (e) { msg = "签到异常: " + e; }
  picac_say(jv, msg);
}

function PICAC_logout(jv, SRC) {
  try { SRC.putLoginHeader(""); } catch (e0) {}
  try { SRC.put("picab_token", ""); } catch (e5) {}
  picac_say(jv, "已退出登录（凭据已清除）");
}

function PICAC_refreshExplore(jv, SRC) {
  var msg = "";
  try {
    SRC.refreshExplore();
    msg = "✅ 发现页已刷新（重新生成签名，请回到发现页）";
  } catch (e) { msg = "刷新失败: " + e; }
  picac_say(jv, msg);
}

/* 源站更新：拉官方 init 地址 → 写入 IP 池 → 刷新发现页 */
function PICAC_updateStation(jv, SRC) {
  var msg = "";
  var r = "";
  try {
    r = String(jv.ajax(PICA.INIT_URL + "?t=" + String(Math.floor(Date.now() / 1000))) || "");
  } catch (e) { r = ""; }
  if (!r) {
    msg = "❌ init 无响应（官方IP服务器不可达），当前源站未变更";
  } else if (r.charAt(0) !== "{") {
    var reason = r.indexOf("SocketTimeout") >= 0 ? "超时"
               : r.indexOf("UnknownHost") >= 0 ? "域名解析失败"
               : r.indexOf("ConnectException") >= 0 ? "连接被拒"
               : "网络错误";
    msg = "❌ init " + reason + "，当前源站未变更";
  } else {
    try {
      var jo = JSON.parse(r);
      var ips = (jo && jo.addresses) || [];
      if (ips.length) {
        var pool = ips.join(",");
        SRC.put("picab_official_ips", pool);
        var st = picac_currentStation(SRC);
        SRC.put("picab_pool", picac_buildPool(st, pool));
        try { SRC.refreshExplore(); } catch (e2) {}
        msg = "✅ 源站更新完成: " + pool + "（当前线路 " + picac_stationName(st) + "）";
      } else {
        msg = "⚠️ init 未返回 IP，当前源站未变更";
      }
    } catch (e3) { msg = "❌ init 返回格式异常，当前源站未变更"; }
  }
  picac_say(jv, msg);
}

/* 选源站：0=官方init 1=Cloudflare 2=系统DNS直连 */
function PICAC_selectStation(jv, SRC, idx) {
  idx = String(idx);
  try {
    SRC.put("picab_station", idx);
    SRC.put("picab_pool", picac_buildPool(idx, picac_official(SRC)));
    try { SRC.refreshExplore(); } catch (e2) {}
    var pool = picac_pool(SRC);
    picac_say(jv, "✅ 已切换源站: " + picac_stationName(idx)
                 + (pool ? "（池 " + pool.split(",").length + " 个IP）" : "（走系统DNS）"));
  } catch (e) {
    picac_say(jv, "切换失败: " + e);
  }
}

function PICAC_showStation(jv, SRC) {
  var st = picac_currentStation(SRC);
  var pool = picac_pool(SRC);
  var off = picac_official(SRC);
  var mode = picac_coverMode(SRC);
  var mname = ({ "ip": "IP直连(Host头)", "dns": "域名直连", "mirror": "镜像站" })[mode] || mode;
  var msg = "当前源站: " + picac_stationName(st)
          + "\nIP池: " + (pool ? pool : "（系统DNS，不设dnsIp）")
          + "\n官方init: " + (off ? off : "（未更新）")
          + "\n封面模式: " + mname;
  picac_say(jv, msg);
}

/* 封面模式：ip / dns / mirror */
function PICAC_setCoverMode(jv, SRC, mode) {
  mode = String(mode);
  try {
    if (mode !== "ip" && mode !== "dns" && mode !== "mirror") {
      picac_say(jv, "❌ 未知封面模式: " + mode);
      return;
    }
    SRC.put("picab_cover_mode", mode);
    var mname = ({ "ip": "IP直连(Host头)", "dns": "域名直连", "mirror": "镜像站" })[mode];
    picac_say(jv, "✅ 封面模式已切换: " + mname + "（重新搜索/刷新详情后生效）");
  } catch (e) {
    picac_say(jv, "切换失败: " + e);
  }
}

function PICAC_setSort(jv, SRC, idx) {
  try { SRC.put("picaSort", String(idx)); } catch (e0) {}
  var names = { "0": "最新发布", "1": "最早发布", "2": "最多爱心", "3": "最多观看" };
  picac_say(jv, "✅ 分类排序已切换: " + names[String(idx)]);
}

function PICAC_setTC(jv, SRC, on) {
  try { SRC.put("picaTC", on ? "1" : "0"); } catch (e0) {}
  picac_say(jv, on ? "✅ 分类/标签显示已切换: 简体" : "✅ 分类/标签显示已切换: 繁体");
